 [Fact]public void OlderSettingsDefaultToNoShutdownAndChoiceCanBeSaved()
 {var old=System.Text.Json.JsonSerializer.Deserialize<Settings>("{\"CapCutPath\":\"CapCut.exe\",\"OutputFolder\":\"test\"}");Assert.NotNull(old);Assert.False(old.ShutdownWhenComplete);var saved=System.Text.Json.JsonSerializer.Serialize(Settings with{ShutdownWhenComplete=true});Assert.True(System.Text.Json.JsonSerializer.Deserialize<Settings>(saved)!.ShutdownWhenComplete);}
 private sealed class ManualClock:TimeProvider
 {private long ticks;public override long TimestampFrequency=>TimeSpan.TicksPerSecond;public override long GetTimestamp()=>ticks;public void Advance(TimeSpan duration)=>ticks+=duration.Ticks;}
 private sealed class Fake(Settings settings):IDesktop
 {
  public List<string> Events=new();public List<string> Actions=new();public bool WrongTitle,WrongPath,NeverSuccess,NoOutput,FailRestart,FailOpen,FailClose,FailShutdown;public CancellationTokenSource? Cancel,CancelOnOpening,CancelOnPolling,CancelOnConfirmation,CancelOnCountdown;public ManualClock? Clock;public List<double> PollSeconds=new();public int SuccessAfterPoll=1;public TimeSpan ScanDuration;public Action<int>? OnPoll;public HashSet<int> MissScans=[];public Func<int,CompletionEvidence> Evidence=_=>new(100,42,12345,100,100);private string name="";private bool started;private long exportStarted;
  public Task Wait(string role,CancellationToken token){token.ThrowIfCancellationRequested();Actions.Add("wait:"+role);return Task.CompletedTask;}
  public Task Click(string role,CancellationToken token){token.ThrowIfCancellationRequested();Actions.Add("click:"+role);if(role=="completion-close")throw new InvalidOperationException("Completion button must not be clicked");if(role=="confirm-export"){started=true;exportStarted=Clock?.GetTimestamp()??0;Events.Add("start:"+name);if(!NoOutput)File.WriteAllText(Path.Combine(settings.OutputFolder,name+".mp4"),"video");Cancel?.Cancel();}return Task.CompletedTask;}
  public Task Search(string n,CancellationToken token){name=n;started=false;Events.Add("search:"+name);return Task.CompletedTask;}
  public Task Pause(TimeSpan duration,CancellationToken token){Actions.Add("pause:"+duration.TotalSeconds);if(Events.Any(x=>x.StartsWith("close:")))CancelOnCountdown?.Cancel();if(duration==TimeSpan.FromSeconds(1))CancelOnConfirmation?.Cancel();if(started)CancelOnPolling?.Cancel();else CancelOnOpening?.Cancel();token.ThrowIfCancellationRequested();Clock?.Advance(duration);return Task.CompletedTask;}
  public Task OpenExportDialog(CancellationToken token){Actions.Add("open-export");if(FailOpen)throw new TimeoutException("No export dialog");CancelOnOpening?.Cancel();token.ThrowIfCancellationRequested();return Task.CompletedTask;}
  public Task<string> ExportTitle(CancellationToken token)=>Task.FromResult("Xuất-"+(WrongTitle?"wrong":name));
  public Task Fill(string role,string value,CancellationToken token){Actions.Add("fill:"+role);return Task.CompletedTask;}
  public Task<string> Read(string role,CancellationToken token)=>Task.FromResult(Path.Combine(settings.OutputFolder,(WrongPath?"wrong":name)+".mp4"));
  public Task ChooseFolder(string folder,CancellationToken token){Actions.Add("folder");return Task.CompletedTask;}
  public Task Select(string menu,string value,CancellationToken token){Actions.Add("select:"+menu);return Task.CompletedTask;}
  public Task<CompletionEvidence?> Success(CancellationToken token){token.ThrowIfCancellationRequested();if(started){PollSeconds.Add(Clock?.GetElapsedTime(exportStarted).TotalSeconds??0);Clock?.Advance(ScanDuration);OnPoll?.Invoke(PollSeconds.Count);}return Task.FromResult(started&&!NeverSuccess&&PollSeconds.Count>=SuccessAfterPoll&&!MissScans.Contains(PollSeconds.Count)?Evidence(PollSeconds.Count):null);}
  public Task Restart(string executable,CompletionEvidence completion,CancellationToken token){token.ThrowIfCancellationRequested();Events.Add("restart:"+name);if(FailRestart)throw new InvalidOperationException("Restart failed");return Task.CompletedTask;}
  public Task CloseCompleted(string executable,CompletionEvidence completion,CancellationToken token){token.ThrowIfCancellationRequested();Events.Add("close:"+name);if(FailClose)throw new InvalidOperationException("Close failed");return Task.CompletedTask;}
  public Task Shutdown(CancellationToken token){token.ThrowIfCancellationRequested();Events.Add("shutdown");if(FailShutdown)throw new InvalidOperationException("Shutdown rejected");return Task.CompletedTask;}

 }
}
